import 'dart:io';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:path_provider/path_provider.dart';
import 'package:shared_preferences/shared_preferences.dart';
void main()=>runApp(const ExpenseLab());
class ExpenseLab extends StatelessWidget{const ExpenseLab({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Pocket Ledger',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:Colors.green),useMaterial3:true),home:const LedgerPage());}
class LedgerPage extends StatefulWidget{const LedgerPage({super.key});@override State<LedgerPage> createState()=>_LedgerPageState();}
class _LedgerPageState extends State<LedgerPage>{final memo=TextEditingController(text:'Coffee - ₹120\\nBus pass - ₹500\\nLunch - ₹180');Future<String>? loaded;String path='Resolving storage location…';@override void initState(){super.initState();_path();}
Future<void> _path()async{try{if(kIsWeb){setState(()=>path='Browser local storage (web fallback)');}else{final d=await getApplicationDocumentsDirectory();setState(()=>path='${d.path}/expenses.txt');}}catch(e){setState(()=>path='Unable to resolve path: $e');}}
Future<void> save()async{try{if(kIsWeb){final p=await SharedPreferences.getInstance();await p.setString('expense_log',memo.text);}else{final d=await getApplicationDocumentsDirectory();await File('${d.path}/expenses.txt').writeAsString(memo.text);}setState(()=>loaded=read());if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Expense log saved')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Save failed: $e')));}}
Future<String> read()async{if(kIsWeb){final p=await SharedPreferences.getInstance();return p.getString('expense_log')??'No expense file saved yet.';}final d=await getApplicationDocumentsDirectory();final f=File('${d.path}/expenses.txt');if(!await f.exists())throw Exception('No expense file found. Save a log first.');return f.readAsString();}
@override void dispose(){memo.dispose();super.dispose();}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Pocket Ledger • File Lab')),body:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Expense log',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:5),Text(path,style:const TextStyle(fontSize:11)),const SizedBox(height:16),TextField(controller:memo,maxLines:6,decoration:const InputDecoration(labelText:'Enter expenses',border:OutlineInputBorder(),alignLabelWithHint:true)),const SizedBox(height:10),Row(children:[Expanded(child:FilledButton.icon(onPressed:save,icon:const Icon(Icons.save),label:const Text('Write file'))),const SizedBox(width:8),Expanded(child:OutlinedButton.icon(onPressed:()=>setState(()=>loaded=read()),icon:const Icon(Icons.folder_open),label:const Text('Read file')))]),const SizedBox(height:16),const Text('Saved contents',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18)),const Divider(),Expanded(child:loaded==null?const Center(child:Text('Choose Read file or Write file.')):FutureBuilder<String>(future:loaded,builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text('⚠ ${s.error}'));return SingleChildScrollView(child:Text(s.data??''));}))])));}
